-- ============================================================
-- STEP 3: Enable Row Level Security on all 5 tables
-- ============================================================

ALTER TABLE public.users             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments          ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;

-- Force RLS even for table owners (good security hygiene)
ALTER TABLE public.users             FORCE ROW LEVEL SECURITY;
ALTER TABLE public.channels          FORCE ROW LEVEL SECURITY;
ALTER TABLE public.posts             FORCE ROW LEVEL SECURITY;
ALTER TABLE public.comments          FORCE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators FORCE ROW LEVEL SECURITY;
"}

