-- ============================================================
-- STEP 4: USERS Table Policies
-- ============================================================

-- Drop any pre-existing policies to ensure clean state
DROP POLICY IF EXISTS "users_select_public_profiles"  ON public.users;
DROP POLICY IF EXISTS "users_update_own_profile"       ON public.users;
DROP POLICY IF EXISTS "users_delete_own_account"       ON public.users;

-- SELECT: Any user can read public profiles (username, created_at visible to all)
-- The row-level check is: is_public = true OR it's the user's own row
CREATE POLICY "users_select_public_profiles"
  ON public.users
  FOR SELECT
  USING (
    is_public = true
    OR id = public.current_user_id()
  );

-- UPDATE: Users can only modify their own profile
CREATE POLICY "users_update_own_profile"
  ON public.users
  FOR UPDATE
  USING (
    id = public.current_user_id()
  )
  WITH CHECK (
    id = public.current_user_id()
  );

-- DELETE: Users can only delete their own account
CREATE POLICY "users_delete_own_account"
  ON public.users
  FOR DELETE
  USING (
    id = public.current_user_id()
  );
"}

{"query": "
-- ============================================================
-- STEP 5: CHANNELS Table Policies
-- ============================================================

DROP POLICY IF EXISTS "channels_select_public"      ON public.channels;
DROP POLICY IF EXISTS "channels_insert_authenticated" ON public.channels;
DROP POLICY IF EXISTS "channels_update_owner_only"  ON public.channels;
DROP POLICY IF EXISTS "channels_delete_owner_only"  ON public.channels;

-- SELECT: Everyone can read public channel information
CREATE POLICY "channels_select_public"
  ON public.channels
  FOR SELECT
  USING (
    is_public = true
    OR owner_id = public.current_user_id()
    OR public.is_channel_moderator(id, public.current_user_id())
  );

-- INSERT: Any authenticated user can create a channel (they become owner)
CREATE POLICY "channels_insert_authenticated"
  ON public.channels
  FOR INSERT
  WITH CHECK (
    public.current_user_id() IS NOT NULL
    AND owner_id = public.current_user_id()   -- enforce owner = creator
  );

-- UPDATE: Only channel owners can modify channel details
CREATE POLICY "channels_update_owner_only"
  ON public.channels
  FOR UPDATE
  USING (
    owner_id = public.current_user_id()
  )
  WITH CHECK (
    owner_id = public.current_user_id()
  );

-- DELETE: Only channel owners can delete channels
CREATE POLICY "channels_delete_owner_only"
  ON public.channels
  FOR DELETE
  USING (
    owner_id = public.current_user_id()
  );
"}

{"query": "
-- ============================================================
-- STEP 8: CHANNEL_MODERATORS Table Policies
-- ============================================================

DROP POLICY IF EXISTS "chanmods_select_all"               ON public.channel_moderators;
DROP POLICY IF EXISTS "chanmods_insert_owner_only"        ON public.channel_moderators;
DROP POLICY IF EXISTS "chanmods_delete_owner_or_self"     ON public.channel_moderators;

-- SELECT: Anyone can see moderator lists for channels
CREATE POLICY "chanmods_select_all"
  ON public.channel_moderators
  FOR SELECT
  USING (true);

-- INSERT: Only channel owners can add moderators
CREATE POLICY "chanmods_insert_owner_only"
  ON public.channel_moderators
  FOR INSERT
  WITH CHECK (
    public.current_user_id() IS NOT NULL
    AND public.is_channel_owner(channel_id, public.current_user_id())
  );

-- DELETE: Channel owners can remove any moderator; moderators can remove themselves
CREATE POLICY "chanmods_delete_owner_or_self"
  ON public.channel_moderators
  FOR DELETE
  USING (
    -- Channel owner can remove anyone
    public.is_channel_owner(channel_id, public.current_user_id())
    -- Moderator can remove themselves
    OR user_id = public.current_user_id()
  );
"}
